		PreRequisitos: [{ "Soco": 2 }],
		Descricao: "O lutador junta as mãos em um grande punho acima da sua cabeça e baixa ambas os braços atingindo com força a cabeça do seu oponente. Dizem que alguns nativo-americanos conseguiriam estontear um búfalo adulto com este lento, porém poderoso, soco.\n\nLutadores de Sumô são proibidos de desferir socos, logo criaram uma variante desta manobra chamada Sumô Slap que usa o mesmo sistema. Na China chamam de Fukkogeki, enquanto lutadores de estilos armados chamam de Buffalo Strike.\n\nExiste uma variação dessa manobra no Wu Shu que se chama Sou Shou Da, onde ao invés de juntar as mãos em um golpe só, e golpeia o oponente com os dois punhos de uma vez só no peito.",
