		Descricao: "Birdie desenvolveu esta explosiva manobra para acabar com os oponntes logo no início das lutas. Assim que o juiz anuncia qu o combate começou, ele gira seu tronco e parte em uma cabeçada poderosíssima contra o oponente, que na melhor das hipóteses é jogado ao chão...quando não é nocauteado. Esta manobra lembra muito o Dashing Punch de Balrog, só que com a cabeça, podendo ser chamada também de Buffalo Headbutt!",
		Sistema: "esta Manobra permite ao lutador se esquivar de projéteis da mesma forma que o Jump, contudo apenas antes de iniciar o seu movimento. O lutador deve se mover em uma linha hexagonal reta, e a manobra causa knockdown.",
