		PreRequisitos: [{ "Soco": 1 }],
		Descricao: "Quando os punhos não resolvem, alguns lutadores usam a cabeça. Muitos estilos praticam cabeçadas como parte do seu arsenal de manobras para lutas a curta distância. Os lutadores devem passar por um treinamento exaustivo para aperfeiçoar esta manobra.\n\nO treino envolve condicionar a testa para agüentar o impacto do golpe: o lutador fica batendo com a cabeça em uma madeira acolchoada, depois madeira pura, depois tijolo e depois pedra. Isto gradualmente endurece a testa do lutador até que ele consiga quebrar praticamente qualquer coisa com uma cabeçada.",
