		Oficial: true,
		Tecnica: "Soco",
		PreRequisitos: [{ "Esportes": 4 }, "Spinning Clothesline"],
		Descricao: "Frustrado pela velocidade de alguns oponentes, Zangief trabalhou duro para tornar o seu Spinning Clothesline mais rápido, também chamado de Cyclone Lariat. Elementais do ar costumam realmente parecer ciclones quando executando esta manobra.",
		Sistema: "este movimento é idêntico ao Spinning Clothesline, exceto que é mais rápido e tem maior alcance.",
		Imagem: "wp-content/uploads/2025/01/turbo-spinning-clothesline.gif",
