		Descricao: "Muitos estilos têm combinações de socos em que um dos punhos desfere dois socos rápidos, ou alternando os punhos para confundir a vítima. Normalmente o primeiro soco acerta no rosto e outro no estômago, ou vice-versa.\n\nBoxeadores chamam esta manobra de One-Two ou Shotgun Combination, enquanto nativos americanos chamam de Gung Ho.",
