		PreRequisitos: [{ "Soco": 3 }, { "Esportes": 3 }, { Ou: [{ "Foco": 2 }, { "Paranormal": 3, Obs: "somente para paranormais" }] }],
		Descricao: "O punho do lutador se envolve em energia e ele se joga contra o oponente, num soco reto ou em arco, atingindo o oponente com as juntas em um punho fechado ou, em alguns casos, com a mão aberta e os dedos dobrados para ganharem rigidez. Lutadores com poderes psíquicos apresentam chamas azuladas (chamando de Psycho Knuckle), enquanto que outros ativam um arco de energia sônica.\n\nNo Aikidô chamam esta manobra de Dash Blast.",
