	"Flash Kick": {
		Slug: "flash-kick",
		Oficial: true,
		Tecnica: "Chute",
		PreRequisitos: [{ "Chute": 3 }, { "Esportes": 2 }, { "Foco": 2 }],
		Descricao: "O conhecido chute de Guile é um dos golpes mais mortais no circuito Street Fighter. Um lutador que tenha dominado este golpe se agacha antes de saltar em uma cambalhota aérea para trás. Conforme seu corpo gira, o pé sobe em um arco mortal à sua frente. Uma trilha de energia segue o pé, adicionando potência ao chute. Quando Guile executa o Flash Kick, faíscas de energia sônica seguem seu pé; outros lutadores lançam arcos de fogo ou eletricidade. O Flash Kick é uma manobra difícil de aprender. Requer uma combinação de esportes para executar a cambalhota para trás, canalização de Chi para liberar a energia e técnica de chute para meter a bota na cara do oponente.\n\nLutadores de Tae Kwon Dô chamam esta manobra de Hi En Zan, enquanto que também é conhecida como Rising Rage Flash por outros lutadores e Scratch Wheel na Africa.",
		Sistema: "use os modificadores abaixo. O Flash Kick também infligirá um Knockdown (derrubar) em oponentes que estejam executando Manobras Aéreas. O próprio Flash Kick é uma Manobra Aérea.",
		Imagem: "wp-content/uploads/2024/03/flash-kick.gif",
	},
