		Descricao: "Esta manobra rapidamente se tornou uma das favoritas entre os Street Fighters iniciantes. Ela é rápida, tem bom alcance e provoca dano considerável. O lutador se lança em um salto longo e rápido, e voa até o oponente, acertando-o com uma joelhada.",
		Sistema: "use os modificadores abaixo. O Flying Knee Thrust é uma Manobra Aérea.",
		Imagem: "wp-content/uploads/2009/01/flying-knee-thrust.gif",
