		Sistema: "role dois testes de dano com os modificadores e caso causar algum dano inflinge knockdown contra oponentes aéreos. Caso o oponente esteja agachado, inflinge apenas um teste de dano e não causa knockdown.\n\nEsta é uma manobra aérea que pode ser utilizada para esquivar de projéteis assim como Jump.",
