		Descricao: "Este chute baixo e poderoso tem como objetivo varrer as pernas do oponente e derrubá-lo no chão com uma rasteira.\n\nNas artes marciais chinesas muitas vezes é chamado de Koshuto (Tiger Assault Toss), onde além da rasteira, usa-se os braços para ajudar o oponente a cair. Na Capoeira é o Lynx Tail, com as duas mãos no chão e rodando as duas pernas para derrubar.",
		Sistema: "vítimas de um Foot Sweep bem sucedido sofrem um Knockdown (são derrubadas) além do dano normal. O Foot Sweep é uma Manobra de Agachamento.",
		Imagem: "wp-content/uploads/2009/01/foot-sweep.gif",
