		Descricao: "Este golpe é muito similar ao Back Flip Kick, exceto que o lutador se lança em uma cambalhota para frente sobre a cabeça do oponente. Quando cai da cambalhota, usa o peso do próprio corpo para acertar com o joelho nas costas do oponente.\n\nChamado de Reverse Ankle pelos praticantes de Baraqah.",
