		Tecnica: "Chute",
		PreRequisitos: [{ "Chute": 2 }, { "Esportes": 1 }, "Foot Sweep"],
		Descricao: "Este movimento é quase idêntico ao Foot Sweep normal, exceto que o lutador faz um giro de 360° ao redor de si mesmo com a perna de chute esticada, derrubando todos que estejam por perto. Esta manobra é às vezes chamada por praticantes de Kung Fu e Wu Shu de vassoura de ferro, cauda do tigre, ou golpe com a cauda do dragão.",
		Sistema: "o lutador rola para dano contra qualquer um que esteja em seu hexágono ou nos seis hexágonos adjacentes a ele. Qualquer vítima que sofre dano também sofre um Knockdown (a menos que a vítima estivesse bloqueando). O Spinning Foot Sweep é uma Manobra de Agachamento.",
		Imagem: "img/2009/11/spinning-foot-sweep.gif",
