		Descricao: "A manobra Wounded Knee é um chute baixo e poderoso em que o lutador atinge com a canela a parte exterior da coxa do oponente, visando o nervo femural. Este golpe enfraquece a perna do oponente, provocando dificuldade de se mover ou chutar.",
		Sistema: "além do dano normal, o ataque Wounded Knee faz com que a vítima sofra, nos próximos dois turnos, penalidades de -2 no Movimento de todas as manobras e -2 na Velocidade de todas as Manobras de Chute.",
