		Descricao: "Com esta manobra, o lutador pode cobrir enormes distâncias e desferir dois estonteantes e mortais ataques no oponente. O lutador avança e executa uma cambalhota para frente, e seus dois pés se encarregam do resto: dois chutes, um alto e outro baixo. O Scissor Kick é eficiente e rápido.",
