		Oficial: true,
		Tecnica: "Chute",
		PreRequisitos: [{ "Chute": 3 }, { "Esportes": 2 }, "Jump"],
		Descricao: "É uma das Manobras mais famosas de Sagat. O lutador começa agachando-se, como um tigre preparando-se para avançar em sua presa, e pula com o joelho contra seu oponente. Tiger Knee é assustadoramente rápido e poderoso.\n\nAlguns lutadores de Muay Thai mais velozes do que fortes, como Adon, chamam-na de Rising Jaguar.",
