		Descricao: "Esta manobra foi desenvolvida por Abel, um dos mais novos Guerreiros Mundiais que dizem ter derrotado o próprio Guile para entrar na tão cobiçada Divisão. Abel faz um movimento um pouco diferente do Ax Kick do Savate. A maior diferença está no fato de Abel se aproveitar de seu tamanho e massa muscular, usando seu peso para aumentar a força do chute, que é desferido de lado, e não de cima para baixo, no tradicional Ax Kick.\n\nA lutadora de Jiu Jitsu Laura Matsuda chama esta manobra de Volty Line, enquanto que lutadores de Muay Thai como Adon chamam de Jaguar Kick, no Africa de Mallet Smash e na Coréia do Sul chamam de Crack Shoot ou de Windmill Kick (sendo que no Tae Kwon Do o giro é quase 360).",
