	"Gekiro": {
		Slug: "gekiro",
		Oficial: false,
		Tecnica: "Chute",
		PreRequisitos: [{ "Chute": 4 }, { "Esportes": 3 }, "Jump"],
		Descricao: "Esta fantástica manobra é uma das ferramentas que o grande sifu Gen utilizou para subir à elite dos Guerreiros Mundiais. Desafiando a gravidade, Gen golpeia seus oponentes violentamente com chutes, fazendo-se erguer no ar, enquanto chuta o oponente e o ergue junto, chute após chute. Ao fim da manobra, Gen cai agachado enquanto sua vítima cai estatelada no chão, possivelmente derrotada.\n\nO treinamento para aprender esta poderosa manobra normalmente é feito com sacos de areia pesando cerca de 300 quilos. Quando os chutes em seqüência do lutador forem fortes o suficiente para levantar o saco de areia, ela estará apto a aprender este golpe que também é chamado de Rising Lightning Leg, Triple Rising Kick, Tenshokyaku (Wu Shu), Spinning Air Kick, Rising Tackle ou Up Kick.",
		Sistema: "esta manobra exige que o lutador use seu único movimento para entrar no mesmo hexágono da vítima. Imediatamente o lutador desfere um chute utilizando os modificadores abaixo. Se causou algum dano no oponente, ele tem direito a um novo chute, e assim por diante, até um máximo de chutes igual à sua técnica de Esportes. Para cada chute bem sucedido (que tenha causado dano) ele ergue a si mesmo e ao oponente no ar, há 1m do chão para cada chute. Ao fim do último chute, o oponente sofre um Knockdown e o lutador termina em um hexágono adjacente ao oponente caído.\n\nNote que durante os chutes o lutador e oponente permanecem no mesmo hexágono. Note também que durante o golpe, o lutador é considerado como executando uma Manobra Aérea e pode se esquivar de manobras de projétil, assim como a manobra Jump.",
		Imagem: "img/2009/11/Gekiro.gif",
	},
	"Flamingo Stance": {
		Slug: "flamingo-stance",
		Oficial: false,
		Tecnica: "Chute",
		PreRequisitos: [{ "Chute": 3 }, { "Esportes": 1 }],
		Descricao: "Assumindo a postura do flamingo, levantando a perna do chute, o lutador consegue golpear com mais efetividade. Em contrapartida, seu movimento é reduzido no processo, pela dificuldade de locomoção com uma só perna.",
		Sistema: "Esta manobra não precisa de uma carta de combate, o lutador decide no começo de seu turno se vai usá-la ou não.\n\nSempre que utilizar sua stance, o lutador recebe um bônus de + 1 na velocidade de qualquer manobra especial de chute que for realizar naquele turno, porém seu movimento fica reduzido a um hexágono apenas (fixo).\n\nAs exceções são quando ele realiza uma manobra aérea, reduzindo pela metade o movimento, ou quando a manobra alterna entre golpes e movimentos, como o Double Dread Kick; neste caso, ele fica impossibilitado de realizar este tipo de manobra. No caso de movimento ímpar, arredonda-se para baixo, podendo inclusive virar nenhum (Mov 1 dividido pela metade).\n\nEssa redução de movimento se aplica mesmo a manobras com movimento fixo (Um, Dois, etc).\n\nA stance acaba quando o lutador sofre um Knock Down, fica atordoado, usa uma manobra que não é chute ou, claro, quando ele decidir encerrar a postura.",
		Imagem: "wp-content/uploads/2025/04/flamingo-stance.gif",
	},
	"Bushin Sempu Kyaku": {
		Slug: "bushin-sempu-kyaku",
		Oficial: false,
		Tecnica: "Chute",
		PreRequisitos: [{ "Chute": 4 }, { "Esportes": 3 }, "Jump", { Ou: [{ "Herança de Clã": 4, Obs: "somente ninjas" }, { Manobra: "Hurricane Kick", Obs: "somente Shotokan" }, { "Elemental": 4, Obs: "somente Elementais" }] }],
		Descricao: "Esta manobra foi criada pelo dojô ninja Bushinryu Genryusai, do qual o ninja Guy é membro. Ela consiste em uma versão modificada do Tatsumaki Sempu Kyaku do dojô de Goutetsu e do Gekiro do Kung Fu, apenas diferenciando-se pelo fato do \"furacão de chutes\" ser executado no mesmo lugar ao invés de percorrer uma linha reta.\n\nPara poder aprender esta manobra, o ninja deve possuir 4 níveis no antecedente único Herança de Clã. Já se o lutador for do estilo Shotokan de Karatê, que chamam este golpe de Tatsumaki Gorasen (Tornado Strong Spiral), o antecedente único não é necessário, mas ele já deve possuir a manobra Hurricane Kick. Na America é chamado de Rising Tackle enquanto outro nome asiático é Bushin Senpuukyaku.",
		Sistema: "esta manobra exige que o lutador use seu único movimento para entrar no mesmo hexágono da vítima. Esta vítima é seu oponente principal e todo funcionamento da manobra gira em torno dele, não sendo possível iniciar a manobra sem ele.\n\nImediatamente o lutador desfere um chute utilizando os modificadores abaixo no oponente principal e em todos os oponentes ao seu redor (hexes adjacentes em todas direções). Se causou algum dano no oponente principal, ele tem direito a um novo chute, e assim por diante, até um máximo de chutes igual à sua técnica de Esportes. Para cada chute bem sucedido (que tenha causado dano) ele ergue a si mesmo e aos oponentes no ar, a 1m do chão para cada chute. Ao fim do último chute desferido (com sucesso ou não), todos oponentes que sofreram ao menos 1 de dano pelos chutes sofrem Knockdown e o lutador termina em um hexágono adjacente de onde começou o golpe.\n\nNote que durante os chutes o lutador e os oponentes não mudam de hexágono. Note também que durante o golpe, o lutador é considerado como executando uma Manobra Aérea e pode se esquivar de manobras de projétil, assim como a manobra Jump, e não pode afetar oponentes que estejam em manobras de agachamento.",
		Imagem: "img/2009/11/Bushin-Sempu-Kyaku.gif",
	},
