		Sistema: "versão semelhante ao Rekka Ken mas com chutes, sem a necessidade do \"show\" ao final e sem o acúmulo para Dizzy.\n\nO Spin Kick é similar a outras Manobras Combo. Durante o primeiro turno do Spin Kick, o jogador usa sua carta da Manobra Especial Spin Kick junto com qualquer uma das três cartas de Manobra Básica de chute (Short, Forward ou Roundhouse). O chute é resolvido normalmente, mas o Spin Kick dá uma Velocidade extra de +2 além do seu nível normal de Velocidade.\n\nPor até mais dois turnos consecutivos, o jogador pode continuar a usar a carta de Spin Kick junto com um chute comum e ganhar o bônus de +2 de Velocidade para o chute.\n\nNo segundo ou terceiro turno consecutivo de Spin Kick você pode usar Foot Sweep ao invés do chute básico (recebendo nele o bônus de +2 Vel), mas isto terminará a sequência de golpes e você não pode dar outro Spin Kick aós um Foot Sweep.",
