	"Deflecting Punch": {
		Slug: "deflecting-punch",
		Oficial: true,
		Tecnica: "Bloqueio",
		PreRequisitos: [{ "Bloqueio": 3 }, { "Soco": 1 }, "Punch Defense"],
		Descricao: "O Wing Chun Kung Fu é famoso por seus rápidos contra-socos, que desviam o soco de um oponente ao mesmo tempo em que o próprio lutador está atacando. Quando o artista marcial vê seu oponente socando, ele contra-ataca com o seu próprio soco, desviando o soco do oponente com seu braço enquanto seu punho continua em frente para atingi-lo.\n\nEssa manobra é chamada de Riposte pelos lutadores de Savate.",
		Sistema: "o lutador deve interromper uma manobra de Soco do oponente. O oponente testa dano para seu soco, mesmo tendo sido interrompido. O lutador ganha o total da sua Absorção de Bloqueio para absorver o dano do oponente. O bloqueio da manobra é útil apenas contra um soco; se o oponente usa qualquer outra Técnica, o lutador não ganha nenhum bônus de bloqueio para seu total de Absorção (mas ainda pode atingir o oponente com o seu contra-soco).\n\nUma vez que o oponente tenha feito seu dano, o lutador imediatamente o atinge com seu contra-soco, a menos que ele tenha sido atordoado (dizzied), jogado para trás ou derrubado (knocked down). O lutador calcula o dano usando sua Técnica de Soco.",
		Imagem: "wp-content/uploads/2009/01/deflecting-punch.jpg",
	},
