	"San He": {
		Slug: "san-he",
		Oficial: true,
		Tecnica: "Bloqueio",
		PreRequisitos: [{ "Bloqueio": 3 }, { "Foco": 2 }],
		Descricao: "Alguns estilos ensinam a seus praticantes a habilidade de enraizar seus corpos no solo usando sua energia Chi interior. Esta mesma energia pode ser espalhada por toda a superfície do corpo, fazendo com que todos os músculos enrijeçam. Esta postura rígida e irremovível é parte da forma San He do Kung Fu. Outros estilos se referem a ela por nomes diferentes. Quando um lutador assume esta postura, seu corpo se torna como um único sólido pedaço de ferro — irremovível e resistente a todos os ataques.",
		Sistema: "quando executa o San He, o personagem adiciona o dobro da sua Técnica de Bloqueio ao total de Absorção.\n\nAlém disso, o personagem usando San He não pode ser derrubado (knockdown) nem jogado para fora de seu hexágono, exceto por uma Manobra de Apresamento. A postura San He enraíza o lutador no solo, e nem poderes especiais como o Hurricane Kick e o Dragon Punch conseguirão jogá-lo para trás. Contra objetos realmente grandes que estejam em movimento, como carros, o Narrador pode pedir que o lutador faça um teste de Força + Bloqueio para se manter no lugar. Quanto maior o objeto, mais sucessos o lutador precisa obter em seu teste (um carro pode exigir quatro sucessos, mas um ônibus pode exigir sete sucessos). O lutador não ganha um bônus de +2 na Velocidade para bloqueios no turno seguinte ao que usou o San He.\n\nExemplo: um personagem com Vigor 3 e uma Técnica de Bloqueio de 4 terá um total de Absorção de 11 no turno em que usar o San He.",
		Imagem: "wp-content/uploads/2009/01/san-he.jpg",
	},

