		Sistema: "similar ao Air Throw, para executar esta manobra durante um combate, o lutador deve interromper uma manobra aérea do oponente. O lutador deverá então saltar para o mesmo hexágono em que sua vitima aérea está e executar a projeção. Se conseguir causar dano, o lutador poderá escolher qualquer ponto dentro de um alcance de três hexágonos para depositar sua vítima. Além do dano normal, a vítima sofre um Knockdown.\n\nDiferente do Air Throw comum, o dano do Air Baton Throw é incrementado de acordo com o bastão utilizado, ficando Força + Apresamento + 4 + mod. dano da arma. Além disso, o Air Baton Throw não permite se movimentar após o dano.",
