		Sistema: "este golpe é um Apresamento Sustentado e causa, além do dano normal, um knockdown no primeiro turno (e que é mantido até a vítima se soltar).\n\nPara que esta manobra seja bem sucedida, o lutador deve executá-la no turno seguinte após ter executado uma Manobra de Bloqueio. Além disso, ele deve ser mais rápido que seu oponente neste turno, para que possa torcer seu braço ou pulso logo depois de ter bloqueado seu ataque e antes do oponente executar outra manobra.\n\nEsta manobra somente pode ser utilizada caso o lutador tenha bloqueado uma Manobra de Soco (somente se o lutador possuir Soco 1 no mínimo) ou uma Manobra de Chute (somente se o lutador possuir Chute 1 no mínimo).",
