	"Baton Throw": {
		Slug: "baton-throw",
		Oficial: false,
		Tecnica: "Apresamento",
		PreRequisitos: [{ "Bastão": 2 }, { "Apresamento": 1 }],
		Descricao: "A maioria das artes marciais ensina técnicas para apresar e projetar oponentes. Estas técnicas envolvem usar os quadris, ombros e/ou os braços para desequilibrar o oponente e alavancá-lo para uma queda.\n\nNo Bojutsu, os alunos aprendem como usar seus bastões para encaixar em pontos como axilas e entre as pernas para fazer alavancas poderosas para derrubá-los no chão.\n\nAlguns lutadores chamam esses movimentos de Luftstorm ou Wirbelwind, a depender de onde encaixam o bastão.",
		Sistema: "similar ao Throw, se a manobra for bem sucedida, o lutador poderá escolher o hexágono no qual seu oponente cairá após a projeção. Um lutador pode projetar um oponente a um número de hexágonos igual à sua Força. O oponente cai no hexágono designado e sofre um Knockdown.\n\nO dano de um Baton Throw é na verdade infligido quando o oponente cai de encontro ao solo, parede, pára-brisa do carro, outro lutador, etc. Se a vítima é jogada sobre outro lutador, o lutador atingido também sofre dano. Role o dano baseado no Vigor do personagem projetado, menos a Absorção total do personagem atingido (Vigor ou Vigor+Bloqueio).\n\nDiferente do Throw, o dano do Baton Throw tem modificador de dano do bastão usado pelo personagem adicionado ao cálculo, ficando Força + Apresamento + 2 + mod. dano da arma.",
		Imagem: "wp-content/uploads/2026/10/luftstorm.png",
	},
