		PreRequisitos: [{ "Apresamento": 2 }],
		Descricao: "Pegue aquele pequeno e irritante lutador e esmague-o contra o peito até rachar seus ossos. Muitos lutadores de luta-livre estão sempre prontos para usar o bom e velho Bear Hug, e alguns lutadores de outros estilos decidiram adotá-lo também.",
		Sistema: "o Bear Hug é um Apresamento Sustentado.",
		Imagem: "wp-content/uploads/2025/01/bear-hug.gif",
