		Oficial: true,
		Tecnica: "Apresamento",
		PreRequisitos: [{ "Apresamento": 3 }],
		Descricao: "O lutador pega seu oponente e aplica um estrangulador Neck Choke. Lutadores grandes como T. Hawk preferem levantar seus oponentes do chão enquanto aplicam o apresamento.",
		Sistema: "o Neck Choke é um Apresamento Sustentado.",
