	"Pile Driver": {
		Slug: "pile-driver",
		Oficial: true,
		Tecnica: "Apresamento",
		PreRequisitos: [{ "Apresamento": 3 }, { "Esportes": 1 }],
		Descricao: "O Pile Driver é uma manobra avançada de apresamento que exige muito treino para ser executada contra um oponente vivo. O lutador deve inverter o corpo do oponente de forma que sua cabeça fique entre as pernas do lutador, e as pernas do oponente se estendam acima da cabeça do lutador. O lutador então pula para cima e levanta as pernas para cair sentado. Quando ambos aterrissam, a cabeça da vítima atinge o solo primeiro.",
		Sistema: "a vítima de um Pile Driver também sofre um Knockdown.",
		Imagem: "wp-content/uploads/2009/12/butsumetsu-buster.gif",
	},
	"Pin": {
		Slug: "pin",
		Oficial: true,
		Tecnica: "Apresamento",
		PreRequisitos: [{ "Apresamento": 2 }],
		Descricao: "Praticantes de Jiu Jitsu aprendem muitas maneiras de manter alguém imóvel. Para executar um Pin o alvo deve ter sofrido um Knockdown ou estar Dizzy; o lutador se move para o hex do oponente e faz a sua rolagem de ataque. Se ele causar dois ou mais níveis de dano, o oponente é mantido em uma dolorosa imobilização até que se liberte - uma tarefa difícil. O praticante de Jiu Jitsu muitas vezes realiza o Pin no seu oponente perto do fim da luta, então apenas espera que o tempo acabe. Esta manobra muitas vezes é comprada como a segunda metade de um combo com Throw e Air Throw.",
		Sistema: "A Força do praticante é considerava elavada em 3 somente para o propósito de segurar o oponente (ela não aumenta a rolagem de dano). O lutador pode escolher infligir dano ou não em cada turno depois do primeiro; o alvo somente usa seu Vigor e Grappling Defense contra este ataque. Este é um Apresamento Sustentado. Se o lutador ficar Dizzy ou nocauteado por um terceiro, o Pin é automaticamente quebrado.",
		Imagem: "wp-content/uploads/2009/08/laura-pin.jpg",
	},
	"Push Body": {
		Slug: "push-body",
		Oficial: false,
		Tecnica: "Apresamento",
		PreRequisitos: [{ "Apresamento": 2 }],
		Descricao: "Nesta manobra o personagem \"gentilmente\" empurra seu oponente com o objetivo de afastá-lo ou derrubá-lo, normalmente sobre uma superfície não muito agradável ou sobre outro oponente.\n\nChamada de Houzantou no Japão.",
		Sistema: "o oponente é jogado a um número de hexágonos igual a Força + Apresamento do atacante e sofre um knockdown.",
		Imagem: "wp-content/uploads/2025/01/push.gif",
	},
	"Ripping Bite": {
		Slug: "ripping-bite",
		Oficial: true,
		Tecnica: "Apresamento",
		PreRequisitos: [{ "Apresamento": 3 }, { Manobra: "Bite", Obs: "Manobra Básica de Híbrido Animal" }],
		Descricao: "Street Fighters Híbridos Animais costumam usar suas presas como armas. O lutador devora embaixo do membro que ele quer enfraquecer, e então tenta rasgar os músculos e ligamentos que se conectam com a pele. Eis o valor dessa manobra (e outras como ela) que Híbridos Animais usam, dentro e forma de torneios.",
		Sistema: "O lutador salta para frente e indica o membro que quer atacar. Um rolamento com sucesso causa dano e provoca no alvo -1 Força e Destreza até o final do combate. A manobra pode ser usada múltiplas vezes, acumulando os redutores no oponente.\n\nQuando for determinar o dano deste ataque, o Antecedente Híbrido Animal é usado no lugar da Técnica Apresamento do híbrido.",
		Imagem: "wp-content/uploads/2026/09/ripping-bite.webp",
	},
