		Descricao: "Ao invés de canalizar eletricidade em oponentes próximos, o kombatente dispara uma rajada elétrica contra um alvo distante.",
		Sistema: "possui um alcance igual Inteligência + Foco, e pode ser esquivado com Jump e similares. Sendo uma Manobra de Projétil, o elemental deve ter uma Linha de Visão livre até seu oponente.\n\nPara efeitos de eletricidade fora de combate, veja o post sobre Shock Treatment.",
