	"Gatotsu": {
		Slug: "gatotsu",
		Oficial: false,
		Tecnica: "Espada",
		PreRequisitos: [{ "Espada": 5 }, { "Esportes": 3 }, "Hirazuki", "Jump", "Zen No Mind"],
		Descricao: "Gatotsu é uma técnica com espada usada pelos Shinsengumi que deriva-se do Hirazuki criado por Hijikata Toshizo, posteriormente modificada por Hajime Saito.\n\nSeu objetivo era ser uma técnica com grande poder destrutivo e quase sem ponto fraco, apenas uma pequena fração do lado direito do corpo que fica exposto.\n\nEla consegue isso pelo fato de ser uma técnica 4 em 1, iniciando com um Hirazuki e prosseguindo com um movimento diferente para cada situação possível: combate longo, próximo e aéreo.",
		Sistema: "o lutador deve baixar a carta de combate do Hirazuki no turno em que usará o Gatotsu, antes de todos escolherem suas cartas, o que demonstrará sua stance atual, indicando inclusive o oponente que irá atacar.\n\nQuando for sua vez de atacar (interrompendo ou não o ataque do oponente), ele pode escolher uma dentre as seguintes formas do Gatotsu (anunciada em voz alta quando for desferir o Gatotsu e sem possibilidade de troca, nem mesmo para manobras de Interrupção):\n\nIshiki: Gatotsu padrão, investida em linha hexagonal reta (todo movimento) contra o oponente selecionado com a espada à frente, podendo inclusive atravessar o hexágono do oponente para efeitos dramáticos (se ainda houver movimento). Velocidade: +2 Dano: +3 Movimento: +2\n\nNishiki: Gatotsu aéreo, o lutador investe sobre seu oponente em uma manobra aérea (que pode esquivar de projéteis como Jump) e desce sobre ele com a espada à frente. Para ser atingido, o oponente deve estar em pé ou agachado, mas não pode estar no ar. Velocidade: +2 Dano: +3 Movimento: +0\n\nSanshiki: Gatotsu anti-aéreo, deve ser usado para interromper lutadores que estejam executando uma manobra aérea, causando Knockdown se inflingir dano. Esta é uma manobra aérea e pode ser usada para esquivar de projéteis e somente causa dano em oponentes que também estejam executando manobras aéreas. Velocidade: +1 Dano: +3 Movimento: -2\n\nZeroshiki: Gatotsu de curta distância e enorme força, quase impossível de evitar. Velocidade: +3 Dano: +5 Movimento: Dois",
		Imagem: "wp-content/uploads/2016/03/gatotsu.gif",
	},
